      margin: 22px 0 0;
      color: var(--muted);
      font-size: 1rem;
      line-height: 1.7;
    }

    .quiz-card {
      padding: 34px;
    }

    .quiz-header {
      display: flex;
      justify-content: space-between;
      gap: 20px;
      align-items: flex-start;
      margin-bottom: 26px;
    }

    .quiz-header h2 {
      margin: 0;
      font-size: 1.5rem;
      letter-spacing: -0.04em;
    }

    .question-count {
      flex: 0 0 auto;
      border-radius: 999px;
      padding: 9px 14px;
      color: var(--primary-dark);
      background: var(--primary-soft);
      font-size: 0.88rem;
      font-weight: 700;
    }

    .form-field {
      padding: 22px;
      border: 1px solid var(--border);
      border-radius: 22px;
      background: var(--surface-soft);
    }

    .form-field + .form-field {
      margin-top: 18px;
    }

    legend {
      display: flex;
      gap: 12px;
      align-items: flex-start;
      width: 100%;
      padding: 0;
      color: var(--text);
