      margin: 10px 0 0 42px;
      color: var(--muted);
      font-size: 0.93rem;
      line-height: 1.55;
    }

    .choice-grid {
      display: grid;
      gap: 12px;
      margin-top: 18px;
    }

    .choice {
      display: flex;
      gap: 12px;
      align-items: center;
      padding: 14px 15px;
      border: 1px solid var(--border);
      border-radius: 16px;
      background: var(--surface);
      cursor: pointer;
      transition: border-color 160ms ease, box-shadow 160ms ease, transform 160ms ease;
    }

    .choice:hover {
      border-color: rgba(79, 70, 229, 0.55);
      box-shadow: 0 10px 24px rgba(79, 70, 229, 0.1);
      transform: translateY(-1px);
    }

    .choice input {
      width: 18px;
      height: 18px;
      accent-color: var(--primary);
    }

    .choice span {
      font-weight: 650;
    }

    .actions {
      display: flex;
      gap: 14px;
      align-items: center;
      margin-top: 24px;
    }

    button {
      border: 0;
      border-radius: 16px;
      padding: 14px 22px;
      color: #ffffff;
      background: var(--primary);
      box-shadow: 0 14px 30px rgba(79, 70, 229, 0.28);
      font: inherit;
      font-weight: 800;
      cursor: pointer;
      transition: background 160ms ease, transform 160ms ease;
    }

    button:hover {
      background: var(--primary-dark);
      transform: translateY(-1px);
    }

    .result {
      margin: 0;
      color: var(--success);
      font-weight: 700;
    }

    @media (max-width: 800px) {
      main {
        padding: 28px 14px;
      }

      .quiz-shell {
        grid-template-columns: 1fr;
      }

      .hero-card {
        position: static;
      }

      .quiz-card {
        padding: 22px;
      }

      .quiz-header,
      .actions {
        flex-direction: column;
        align-items: stretch;
      }
    }
  </style>
</head>
<body>
  <main id="app"></main>

  <script>
    const quizQuestions = [
      {
        id: "language-types",
        prompt: "Which of these are programming languages?",
        helpText: "Select every option that is commonly used to write software. More than one answer may be correct.",
        choices: ["Python", "HTML", "JavaScript", "Ruby"]
      },
      {
        id: "web-languages",
        prompt: "Which languages are commonly used for web development?",
        choices: ["JavaScript", "TypeScript", "Swift", "PHP"]
      },
      {
        id: "compiled-languages",
        prompt: "Which languages are typically compiled before running?",
        choices: ["C++", "Go", "Rust", "SQL"]
      }
    ];

    const Choice = ({ questionId, choice }) => `
      <label class="choice">
        <input type="checkbox" name="${questionId}" value="${choice}">
        <span>${choice}</span>
      </label>
    `;

    const Question = ({ question, index }) => `
      <div class="form-field">
        <fieldset>
          <legend>
            <span class="question-number">${index + 1}</span>
            <span>${question.prompt}</span>
          </legend>
          ${question.helpText ? `<p class="help-text">${question.helpText}</p>` : ""}
          <div class="choice-grid">
            ${question.choices.map((choice) => Choice({ questionId: question.id, choice })).join("")}
          </div>
        </fieldset>
      </div>
    `;

    const QuizForm = ({ questions }) => `
      <section class="quiz-card" aria-labelledby="quiz-title">
        <div class="quiz-header">
          <div>
            <h2 id="quiz-title">Choose all correct answers</h2>
          </div>
          <span class="question-count">${questions.length} questions</span>
        </div>
        <form id="quiz-form">
          ${questions.map((question, index) => Question({ question, index })).join("")}
          <div class="actions">
            <button type="submit">Submit answers</button>
            <p class="result" id="result" role="status" aria-live="polite"></p>
          </div>
        </form>
      </section>
    `;

    const App = () => `
      <div class="quiz-shell">
        <aside class="hero-card">
          <p class="eyebrow">Computer languages</p>
          <h1>Quick language quiz</h1>
          <p class="hero-copy">
            Test your knowledge of programming and web languages with a short multi-select quiz.
          </p>
        </aside>
        ${QuizForm({ questions: quizQuestions })}
      </div>
    `;

    document.getElementById("app").innerHTML = App();

    document.getElementById("quiz-form").addEventListener("submit", (event) => {
      event.preventDefault();

      const answeredCount = quizQuestions.filter((question) =>
        document.querySelectorAll(`input[name="${question.id}"]:checked`).length > 0
      ).length;

      document.getElementById("result").textContent =
        `Submitted ${answeredCount} of ${quizQuestions.length} questions.`;
    });
  </script>
</body>
</html>
